public int makingAnagrams(String a, String b) {
    int[] fa = new int[26];
    int[] fb = new int[26];
    for (char c : a.toCharArray()) fa[c - 'a']++;
    for (char c : b.toCharArray()) fb[c - 'a']++;
    int deletions = 0;
    for (int i = 0; i < 26; i++) {
        deletions += Math.abs(fa[i] - fb[i]);
    }
    return deletions;
}

