public int makingAnagrams(String a, String b) {
    int[] balance = new int[26];
    for (char c : a.toCharArray()) balance[c - 'a']++;
    for (char c : b.toCharArray()) balance[c - 'a']--;
    int deletions = 0;
    for (int v : balance) {
        deletions += Math.abs(v);
    }
    return deletions;
}

code.python:
def making_anagrams(self, a: str, b: str) -> int:
    balance = [0] * 26
    for ch in a:
        balance[ord(ch) - 97] += 1
    for ch in b:
        balance[ord(ch) - 97] -= 1
    return sum(abs(v) for v in balance)
